    assert parse_binary("1" * 64) == 2**64 - 1
    assert parse_binary("1" + "0" * 100) == 2**100


@pytest.mark.parametrize("bad", ["2", "12", "1a", "10z1", "9"])
def test_rejects_digits_other_than_0_and_1(bad):
