        result = say(number)
        assert isinstance(result, str), f"say({number}) returned {type(result).__name__}, expected str"
        assert result.strip() != "", f"say({number}) returned an empty string"


def test_zero_example():
    """REQ: "0 → zero" """
    assert say(0) == "zero"


def test_one_example():
    """REQ: "1 → one" """
