        shifts = [ord(k) - ord('a') for k in self.key]
        out = []
        for i, ch in enumerate(text):
            s = shifts[i % len(shifts)] * sign
            out.append(chr((ord(ch) - ord('a') + s) % 26 + ord('a')))
        return ''.join(out)

    def encode(self, text):
        return self._shift(text, 1)

    def decode(self, text):
        return self._shift(text, -1)
